class Node:
    def __init__(self, val):
        self.val, self.next = val, None

def merge(l1, l2):
    dummy = Node(0)
    tail = dummy
    while l1 and l2:
        if l1.val <= l2.val:
            tail.next, l1 = l1, l1.next
        else:
            tail.next, l2 = l2, l2.next
        tail = tail.next
    tail.next = l1 or l2
    return dummy.next

def build(vals):
    dummy = Node(0)
    cur = dummy
    for v in vals:
        cur.next = Node(v)
        cur = cur.next
    return dummy.next

m = merge(build([1, 2, 4]), build([1, 3, 4]))
out = []
while m:
    out.append(m.val)
    m = m.next
